package com.lovemaptually.controller;import com.lovemaptually.auth.CurrentUser;import com.lovemaptually.common.ApiResponse;import com.lovemaptually.dto.request.CreateRecommendationRequest;import com.lovemaptually.dto.response.*;import com.lovemaptually.service.RecommendationService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") @RequiredArgsConstructor public class RecommendationController {private final RecommendationService service;@PostMapping("/groups/{gid}/recommendation-requests")ResponseEntity<ApiResponse<RecommendationAcceptedResponse>>create(Authentication a,@PathVariable long gid,@Valid@RequestBody CreateRecommendationRequest b){return ResponseEntity.accepted().body(ApiResponse.of(202,"추천을 준비하고 있습니다",service.create(gid,CurrentUser.id(a),b.query())));}@GetMapping("/recommendation-requests/{id}")ApiResponse<RecommendationResultResponse>get(Authentication a,@PathVariable long id){return ApiResponse.of(200,"조회했습니다",service.get(id,CurrentUser.id(a)));}}
